<?php require 'partials.php'; $order=null;$err=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$q=db()->prepare("SELECT o.order_code,o.service,o.service_date,o.status,o.created_at,c.name,c.phone FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.order_code=? AND c.phone=?");$q->execute([trim($_POST['kode']??''),trim($_POST['telepon']??'')]);$order=$q->fetch();if(!$order)$err='Pesanan tidak ditemukan. Periksa kembali kode dan nomor WhatsApp.';}catch(Throwable $e){$err='Database belum siap.';}} site_header('Cek Pesanan'); ?>
<section class="page-hero"><div class="container"><h1>Cek Status Pesanan</h1><p>Masukkan kode pesanan dan nomor WhatsApp yang digunakan saat memesan.</p></div></section><section class="content container"><div class="panel" style="max-width:620px;margin:auto"><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="field"><label>Kode pesanan</label><input name="kode" required placeholder="Contoh: KS261117ABC123"></div><div class="field"><label>Nomor WhatsApp</label><input name="telepon" required placeholder="Nomor saat pemesanan"></div><button class="btn">Cek Status</button></form><?php if($err): ?><p class="notice"><?= e($err) ?></p><?php endif; ?><?php if($order): ?><div class="notice success"><b><?= e($order['order_code']) ?></b><br><?= e($order['service']) ?> — <?= e($order['service_date']) ?><br>Status: <b><?= e($order['status']) ?></b></div><?php endif; ?></div></section><?php site_footer(); ?>
